using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Text;
using System.Text.RegularExpressions;
using System.Xml;
using System.Xml.Linq;
using System.Security.Cryptography;
using System.Web.Script.Serialization;
using Microsoft.Win32;
using System.Runtime.InteropServices;
public static class NativeInstaller {
 static NativeInstaller(){AppContext.SetSwitch("Switch.System.IO.UseLegacyPathHandling",false);AppContext.SetSwitch("Switch.System.IO.BlockLongPaths",false);}
 const string PanelRel="SimObjects/Airplanes/prosim-b738-2026/panel/panel.cfg", SoundRel="SimObjects/Airplanes/prosim-b738-2026/sound/sound.xml";
 static readonly UTF8Encoding Utf8=new UTF8Encoding(false);
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=64000000};
 public static XmlDocument ReadXml(string path){var doc=new XmlDocument{PreserveWhitespace=true,XmlResolver=null};try{doc.Load(path);return doc;}catch(XmlException){byte[] bytes=File.ReadAllBytes(path);if(bytes.Length>1&&((bytes[0]==255&&bytes[1]==254)||(bytes[0]==254&&bytes[1]==255)))throw;
  int skip=bytes.Length>=3&&bytes[0]==239&&bytes[1]==187&&bytes[2]==191?3:0;bool bad=false;try{new UTF8Encoding(false,true).GetString(bytes,skip,bytes.Length-skip);}catch(DecoderFallbackException){bad=true;}if(!bad)throw;
  string text=Encoding.GetEncoding(1252).GetString(bytes,skip,bytes.Length-skip);var decl=Regex.Match(text,"^\\s*<\\?xml[^?]*encoding\\s*=\\s*[\"']([^\"']+)[\"']");if(decl.Success&&!Regex.IsMatch(decl.Groups[1].Value,"^(utf-8|utf8)$",RegexOptions.IgnoreCase))throw;
  text=Regex.Replace(text,"(?i)(<\\?xml[^?]*encoding\\s*=\\s*)[\"'][^\"']+[\"']","$1\"utf-8\"");doc.LoadXml(text);return doc;}}
 static void SaveXml(XmlDocument doc,string path){var declaration=doc.FirstChild as XmlDeclaration;if(declaration!=null)declaration.Encoding="utf-8";using(var writer=XmlWriter.Create(path,new XmlWriterSettings{Encoding=Utf8,Indent=false,NewLineHandling=NewLineHandling.None}))doc.Save(writer);}
 static string Hash(string path){using(var sha=SHA256.Create())using(var stream=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");}
 static void CopyTree(string from,string to){Directory.CreateDirectory(to);foreach(string file in Directory.GetFiles(from)){File.Copy(file,Path.Combine(to,Path.GetFileName(file)),true);}foreach(string dir in Directory.GetDirectories(from)){if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked package directories are not supported: "+dir);CopyTree(dir,Path.Combine(to,Path.GetFileName(dir)));}}
 static void RemovePackage(string path,string community){string expected=Path.GetFullPath(Path.Combine(community,"gsx-jetway-bell"));if(!String.Equals(Path.GetFullPath(path),expected,StringComparison.OrdinalIgnoreCase)||!String.Equals(Path.GetDirectoryName(expected),Path.GetFullPath(community).TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new Exception("Invalid package removal path.");if(Directory.Exists(path)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new Exception("The bell package must not be a directory link.");foreach(string dir in Directory.GetDirectories(path,"*",SearchOption.AllDirectories))if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked package content cannot be removed.");Directory.Delete(path,true);}}
 static IEnumerable<Dictionary<string,object>> Rows(object array){return ((IEnumerable)array).Cast<object>().Select(x=>(Dictionary<string,object>)x);}
 static void UpdateLayout(string aircraft){string path=Path.Combine(aircraft,"layout.json");var layout=(Dictionary<string,object>)Json.DeserializeObject(File.ReadAllText(path));var entries=Rows(layout["content"]).ToList();foreach(string relative in new[]{PanelRel,SoundRel}){var matches=entries.Where(x=>String.Equals((string)x["path"],relative,StringComparison.OrdinalIgnoreCase)).ToList();if(matches.Count>1)throw new Exception("Duplicate layout entry: "+relative);var item=new FileInfo(Path.Combine(aircraft,relative));var row=matches.Count==1?matches[0]:new Dictionary<string,object>{{"path",relative}};row["size"]=item.Length;row["date"]=item.LastWriteTimeUtc.ToFileTimeUtc();if(matches.Count==0)entries.Add(row);}layout["content"]=entries;File.WriteAllText(path,Json.Serialize(layout),Utf8);}
 static bool Ours(XmlElement node){return Regex.IsMatch(node.GetAttribute("FileName"),"^GSX_Jetway_(Bell(_Cabin|_Open)?|Custom_[A-Z0-9]{4}_(Cabin|Open))$")&&Regex.IsMatch(node.GetAttribute("LocalVar"),"^GSX_JETWAY_BELL_(ACTIVE|DEFAULT_ACTIVE|AIRPORT_[A-Z0-9]{4}_ACTIVE)$");}
 static void RemoveSounds(XmlDocument doc){foreach(XmlElement node in doc.SelectNodes("//Sound").Cast<XmlElement>().ToArray())if(Ours(node))node.ParentNode.RemoveChild(node);}
 static string RemoveGauge(string text){var kept=new List<string>();foreach(string section in Regex.Split(text,"(?m)(?=^\\[)")){if(!Regex.IsMatch(section,"(?im)^htmlgauge\\d+\\s*=\\s*GSXJetwayBell/JetwayBell\\.html")){kept.Add(section);continue;}string clean=Regex.Replace(section,"(?im)^htmlgauge\\d+\\s*=\\s*GSXJetwayBell/JetwayBell\\.html[^\\r\\n]*\\r?\\n?","");string substantive=Regex.Replace(clean,"(?im)^\\s*(\\[VCockpit\\d+\\]|;[^\\r\\n]*|size_mm\\s*=\\s*1,1|pixel_size\\s*=\\s*1,1|texture\\s*=\\s*NO_TEXTURE)\\s*$","").Trim();if(substantive.Length>0)kept.Add(clean);}return Regex.Replace(String.Concat(kept),"(?im)^; GSX bell: invisible manager, no external application\\.\\r?\\n?","");}
 static XmlElement AddSound(XmlDocument doc,string eventName,string file,string trigger,string view,string volume){var node=doc.CreateElement("Sound");string[,] attrs={{"WwiseData","false"},{"WwiseEvent",eventName},{"FileName",file},{"LocalVar",trigger},{"Continuous","true"},{"BreakOnStop","false"},{"FadeOutType","0"},{"ViewPoint",view},{"MuteOnVPChange","true"},{"Panning","-5000"},{"FullScaleDistance","0"}};for(int i=0;i<attrs.GetLength(0);i++)node.SetAttribute(attrs[i,0],attrs[i,1]);var range=doc.CreateElement("Range");range.SetAttribute("LowerBound","1");range.SetAttribute("UpperBound","1");node.AppendChild(range);var curve=doc.CreateElement("VolumeCurve");curve.SetAttribute("LocalVar",volume);curve.SetAttribute("Units","number");foreach(string v in new[]{"0","100"}){var point=doc.CreateElement("Point");point.SetAttribute("SimValue",v);point.SetAttribute("Output",v);curve.AppendChild(point);}node.AppendChild(curve);doc.SelectSingleNode("/SoundInfo/SimVarSounds").AppendChild(node);return node;}
 static string AllocateWaveSlot(XmlDocument doc){
  foreach(string family in new[]{"custom_sound","custom_misc_sound","custom_instrument_sound","custom_ground_sound","custom_rattle_sound"})for(int slot=1;slot<=12;slot++){
   string name=family+"_"+slot.ToString("D2");
   bool used=doc.SelectNodes("//Sound").Cast<XmlElement>().Any(n=>String.Equals(n.GetAttribute("WwiseEvent"),name,StringComparison.OrdinalIgnoreCase));
   if(!used)return name;
  }
  throw new Exception("No supported WAV sound slots remain for another airport override. Remove an override or retain the default bell.");
 }
 static void AddVariants(XmlDocument doc,string code){string prefix=code==""?"GSX_Jetway_Bell":"GSX_Jetway_Custom_"+code;string trigger=code==""?"GSX_JETWAY_BELL_DEFAULT_ACTIVE":"GSX_JETWAY_BELL_AIRPORT_"+code+"_ACTIVE";foreach(int slot in new[]{10,11,12}){string id="custom_sound_"+slot;string eventName=code==""?id:AllocateWaveSlot(doc);if(doc.SelectSingleNode("//Sound[@WwiseEvent='"+eventName+"']")!=null)throw new Exception("Sound event already used: "+eventName);AddSound(doc,eventName,prefix+(slot==10?"_Open":"_Cabin"),trigger,slot==11?"Outside":"Inside",slot==10?"GSX_BELL_OPEN_VOLUME":slot==11?"GSX_BELL_PLAYBACK_VOLUME":"GSX_BELL_CLOSED_VOLUME");}}
 static string Source(string home,string relative){if(!Regex.IsMatch(relative??"","^Sounds/[a-fA-F0-9]{32}\\.wav$"))throw new Exception("Invalid custom recording path.");string path=Path.Combine(home,"UserData",relative);BellAudio.Validate(path);return path;}
 static void PrepareSounds(string home,string staged,XmlDocument sound){string config=Path.Combine(home,@"UserData\settings.xml");var settings=File.Exists(config)?XDocument.Load(config):new XDocument(new XElement("SoundSettings"));if(settings.Root==null||settings.Root.Name!="SoundSettings")throw new Exception("Invalid sound settings.");string audio=Path.Combine(staged,"SimObjects/Airplanes/prosim-b738-2026/sound");var def=settings.Root.Element("Default");string file=def==null?"":(string)def.Attribute("file");if(!String.IsNullOrEmpty(file)){string source=Source(home,file);BellAudio.Prepare(source,Path.Combine(audio,"GSX_Jetway_Bell.wav"),false);BellAudio.Prepare(source,Path.Combine(audio,"GSX_Jetway_Bell_Cabin.wav"),false);BellAudio.Prepare(source,Path.Combine(audio,"GSX_Jetway_Bell_Open.wav"),true);}AddVariants(sound,"");var codes=new SortedSet<string>(StringComparer.Ordinal);
  foreach(var item in settings.Root.Elements("Airport")){string code=((string)item.Attribute("icao")??"").ToUpperInvariant();if(!Regex.IsMatch(code,"^[A-Z0-9]{4}$")||!codes.Add(code))throw new Exception("Invalid or duplicate airport ICAO.");string source=Source(home,(string)item.Attribute("file"));foreach(string variant in new[]{"Cabin","Open"})BellAudio.Prepare(source,Path.Combine(audio,"GSX_Jetway_Custom_"+code+"_"+variant+".wav"),variant=="Open");AddVariants(sound,code);}
  string runtime=Path.Combine(staged,"html_ui/Pages/VCockpit/Instruments/GSXJetwayBell/JetwayBellRuntime.js");File.WriteAllText(runtime,"window.GSXBellAirports = "+Json.Serialize(codes.ToArray())+";\r\n"+File.ReadAllText(runtime),Utf8);
  var entries=Directory.GetFiles(staged,"*",SearchOption.AllDirectories).Where(x=>Path.GetFileName(x)!="layout.json").Select(x=>{var info=new FileInfo(x);return new{path=x.Substring(staged.Length+1).Replace('\\','/'),size=info.Length,date=info.LastWriteTimeUtc.ToFileTimeUtc()};});File.WriteAllText(Path.Combine(staged,"layout.json"),Json.Serialize(new{content=entries.ToArray()}),Utf8);
 }
 static void VerifyOwned(string home,string package,string baseline,bool uninstall){if(!Directory.Exists(package))return;if((File.GetAttributes(package)&FileAttributes.ReparsePoint)!=0)throw new Exception("The bell package must not be a directory link.");string manifest=Path.Combine(home,"installed-files.json");var hashes=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(File.Exists(manifest))foreach(var row in Rows(Json.DeserializeObject(File.ReadAllText(manifest))))hashes[(string)row["path"]]=(string)row["hash"];
  foreach(string path in Directory.GetFiles(package,"*",SearchOption.AllDirectories)){string rel=path.Substring(package.Length+1);string hash;if(hashes.TryGetValue(rel,out hash)){if(!String.Equals(Hash(path),hash,StringComparison.OrdinalIgnoreCase))throw new Exception("Package file changed; retained: "+rel);}else if(!File.Exists(Path.Combine(baseline,rel))||(uninstall&&!String.Equals(Hash(path),Hash(Path.Combine(baseline,rel)),StringComparison.OrdinalIgnoreCase)))throw new Exception("Unrecognized package file; retained: "+rel);}
 }
 public static string Run(string home,string community,bool uninstall,bool register,string installedExe=null){
  if(System.Diagnostics.Process.GetProcessesByName("FlightSimulator2024").Length>0||System.Diagnostics.Process.GetProcessesByName("FlightSimulator").Length>0)throw new Exception("Close MSFS completely first.");
  community=Path.GetFullPath(community).TrimEnd(Path.DirectorySeparatorChar);if(!Directory.Exists(community))throw new Exception("Community folder does not exist.");string aircraft=Path.Combine(community,"prosim-b738"),panel=Path.Combine(aircraft,PanelRel),soundPath=Path.Combine(aircraft,SoundRel),layout=Path.Combine(aircraft,"layout.json"),package=Path.Combine(community,"gsx-jetway-bell"),baseline=Path.Combine(home,"gsx-jetway-bell");foreach(string file in new[]{panel,soundPath,layout})if(!File.Exists(file))throw new Exception("Required ProSim file missing: "+file);
  VerifyOwned(home,package,baseline,uninstall);var sound=ReadXml(soundPath);if(sound.SelectSingleNode("/SoundInfo/SimVarSounds")==null)throw new Exception("Aircraft SimVarSounds container missing.");var layoutCheck=(Dictionary<string,object>)Json.DeserializeObject(File.ReadAllText(layout));Rows(layoutCheck["content"]).ToList();
  // Upgrade neutral/legacy identifiers in memory only; originals are backed up below.
  foreach(XmlElement node in sound.SelectNodes("//Sound[contains(@FileName,'GSX_Jetway_Bell')]").Cast<XmlElement>()){foreach(string attr in new[]{"FileName","LocalVar"})node.SetAttribute(attr,Regex.Replace(node.GetAttribute(attr),"^[^_]+_(GSX_)","$1"));}
  RemoveSounds(sound);string panelText=RemoveGauge(Regex.Replace(File.ReadAllText(panel),@"\b\w*GSXJetwayBell/JetwayBell\.html","GSXJetwayBell/JetwayBell.html"));
  string backup=Path.Combine(home,"backup-native-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Directory.CreateDirectory(backup);File.Copy(panel,Path.Combine(backup,"panel.cfg"));File.Copy(soundPath,Path.Combine(backup,"sound.xml"));File.Copy(layout,Path.Combine(backup,"layout.json"));string ownership=Path.Combine(home,"installed-files.json");bool hadOwnership=File.Exists(ownership);if(hadOwnership)File.Copy(ownership,Path.Combine(backup,"installed-files.json"));bool hadPackage=Directory.Exists(package);if(hadPackage)CopyTree(package,Path.Combine(backup,"gsx-jetway-bell"));
  string staged=Path.Combine(backup,"staged-package");bool mutated=false;
  try{
   if(!uninstall){CopyTree(baseline,staged);PrepareSounds(home,staged,sound);int next=1;foreach(Match m in Regex.Matches(panelText,@"(?im)^\[VCockpit(\d+)\]"))next=Math.Max(next,Int32.Parse(m.Groups[1].Value)+1);panelText+="\r\n; GSX bell: invisible manager, no external application.\r\n[VCockpit"+next.ToString("D2")+"]\r\nsize_mm=1,1\r\npixel_size=1,1\r\ntexture=NO_TEXTURE\r\nhtmlgauge00=GSXJetwayBell/JetwayBell.html,0,0,1,1\r\n";}
   mutated=true;File.WriteAllText(panel,panelText,Utf8);SaveXml(sound,soundPath);UpdateLayout(aircraft);RemovePackage(package,community);if(!uninstall){CopyTree(staged,package);var hashes=Directory.GetFiles(package,"*",SearchOption.AllDirectories).Select(x=>new{path=x.Substring(package.Length+1),hash=Hash(x)}).ToArray();File.WriteAllText(Path.Combine(home,"installed-files.json"),Json.Serialize(hashes),Utf8);}string shortcutWarnings=register?Register(home,community,uninstall,installedExe):"";
   return (uninstall?"Uninstalled bell integration and package. Custom sounds/settings and recovery backups were retained.":"Installed version 1.2.9. Sound Settings and custom recordings were preserved.")+"\r\nRecovery backup: "+backup+shortcutWarnings;
  }catch{if(mutated){File.Copy(Path.Combine(backup,"panel.cfg"),panel,true);File.Copy(Path.Combine(backup,"sound.xml"),soundPath,true);File.Copy(Path.Combine(backup,"layout.json"),layout,true);RemovePackage(package,community);if(hadPackage)CopyTree(Path.Combine(backup,"gsx-jetway-bell"),package);if(hadOwnership)File.Copy(Path.Combine(backup,"installed-files.json"),ownership,true);else if(File.Exists(ownership))File.Delete(ownership);}throw;}
 }
 static string Register(string home,string community,bool uninstall,string installedExe){
  const string key=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\GSXJetwayBellProSim";string exe=installedExe??Path.Combine(home,"Setup.exe");
  if(uninstall)Registry.CurrentUser.DeleteSubKeyTree(key,false);
  else using(var entry=Registry.CurrentUser.CreateSubKey(key)){
   entry.SetValue("DisplayName","Jetway Bell For ProSim737 on MSFS 2024 with GSX");entry.SetValue("DisplayVersion","1.2.9");entry.SetValue("InstallLocation",home);entry.SetValue("CommunityRoot",community);entry.SetValue("Publisher","GSX Jetway Bell");entry.SetValue("UninstallString","\""+exe+"\" /uninstall");entry.SetValue("ModifyPath","\""+exe+"\" /settings");entry.SetValue("DisplayIcon",exe);entry.SetValue("NoModify",0);entry.SetValue("NoRepair",1);
  }
  return ShortcutManager.Configure(home,exe,uninstall);
 }
}
